content:
Below is a clean Terraform module layout that provisions:

- **S3 bucket** with:
  - versioning
  - encryption
  - public access blocked
- **RDS PostgreSQL** with:
  - deletion protection
  - backup retention
  - not publicly accessible
- **IAM role for service accounts**
  - supports OIDC trust for Kubernetes service accounts
  - least-privilege S3 access policy

It also supports **dev/prod** via **tfvars** and can be used with **workspaces** if you prefer.

---

# Suggested structure

```text
terraform/
├── modules/
│   ├── app_bucket/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── postgres_rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam_service_account_role/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── env/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
├── versions.tf
└── provider.tf
```

---

# Root module

## `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

## `provider.tf`

```hcl
provider "aws" {
  region = var.aws_region
}
```

## `variables.tf`

```hcl
variable "aws_region" {
  type = string
}

variable "environment" {
  type = string
}

variable "name_prefix" {
  type = string
}

variable "tags" {
  type    = map(string)
  default = {}
}

# Networking for RDS
variable "db_subnet_ids" {
  type = list(string)
}

variable "db_security_group_ids" {
  type = list(string)
}

# RDS settings
variable "db_name" {
  type = string
}

variable "db_username" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "db_instance_class" {
  type = string
}

variable "db_allocated_storage" {
  type = number
  default = 20
}

variable "db_multi_az" {
  type = bool
  default = false
}

variable "db_backup_retention_period" {
  type    = number
  default = 7
}

variable "db_engine_version" {
  type    = string
  default = "15"
}

# Bucket
variable "bucket_force_destroy" {
  type    = bool
  default = false
}

variable "bucket_replication_enabled" {
  type    = bool
  default = false
}

variable "bucket_replication_destination_arn" {
  type    = string
  default = null
}

# IAM / OIDC
variable "oidc_provider_arn" {
  type = string
}

variable "oidc_provider_url" {
  type = string
}

variable "k8s_namespace" {
  type = string
}

variable "k8s_service_account_name" {
  type = string
}
```

## `main.tf`

```hcl
locals {
  common_tags = merge(var.tags, {
    Environment = var.environment
    ManagedBy   = "terraform"
  })
}

module "app_bucket" {
  source = "./modules/app_bucket"

  bucket_name                         = "${var.name_prefix}-${var.environment}-assets"
  force_destroy                       = var.bucket_force_destroy
  enable_replication                  = var.bucket_replication_enabled
  replication_destination_bucket_arn  = var.bucket_replication_destination_arn
  tags                                = local.common_tags
}

module "postgres_rds" {
  source = "./modules/postgres_rds"

  identifier               = "${var.name_prefix}-${var.environment}-postgres"
  db_name                  = var.db_name
  username                 = var.db_username
  password                 = var.db_password
  engine_version           = var.db_engine_version
  instance_class           = var.db_instance_class
  allocated_storage        = var.db_allocated_storage
  multi_az                 = var.db_multi_az
  backup_retention_period  = var.db_backup_retention_period
  subnet_ids               = var.db_subnet_ids
  vpc_security_group_ids   = var.db_security_group_ids
  publicly_accessible      = false
  deletion_protection      = true
  storage_encrypted        = true
  tags                     = local.common_tags
}

module "iam_service_account_role" {
  source = "./modules/iam_service_account_role"

  role_name                 = "${var.name_prefix}-${var.environment}-sa-role"
  oidc_provider_arn         = var.oidc_provider_arn
  oidc_provider_url         = var.oidc_provider_url
  namespace                 = var.k8s_namespace
  service_account_name      = var.k8s_service_account_name
  s3_bucket_arn             = module.app_bucket.bucket_arn
  tags                      = local.common_tags
}
```

## `outputs.tf`

```hcl
output "bucket_name" {
  value = module.app_bucket.bucket_name
}

output "bucket_arn" {
  value = module.app_bucket.bucket_arn
}

output "rds_endpoint" {
  value = module.postgres_rds.endpoint
}

output "rds_address" {
  value = module.postgres_rds.address
}

output "iam_role_arn" {
  value = module.iam_service_account_role.role_arn
}
```

